var areConnected = function(n, threshold, queries) {
    const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
    const adj = Array.from({length: n + 1}, () => []);
    for (let x = 1; x <= n; x++)
        for (let y = x + 1; y <= n; y++)
            if (gcd(x, y) > threshold) {
                adj[x].push(y);
                adj[y].push(x);
            }
    return queries.map(([a, b]) => {
        const seen = new Set([a]);
        const queue = [a];
        while (queue.length) {
            const u = queue.shift();
            for (const v of adj[u]) {
                if (!seen.has(v)) {
                    seen.add(v);
                    queue.push(v);
                }
            }
        }
        return seen.has(b);
    });
};

